<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {state,catalog,resolve,readiness,transact,act} from '../workbench/store';
import {objectKey,kinds,aspectNames as aspectNamesSource} from '../workbench/model';
import {route,go,setQuery,openObject,back} from '../workbench/navigation';
import {newObject,editObject} from '../workbench/ui';
import ModelLink from './ModelLink.vue';
import ModelObjectContent from './ModelObjectContent.vue';
import PagingBar from './PagingBar.vue';
import ObjectDrafts from './ObjectDrafts.vue';
const aspectNames=aspectNamesSource;
const title=computed(()=>({'textbooks':'教材管理','targets':'目标管理','learning-spaces':'学习空间管理'}[route.page]||'课程准备'));
const selected=computed(()=>resolve(route.id.split('@')[0]||''));
const prep=computed(()=>state.preparations.find(p=>p.chapter===selected.value?.id));
const note=ref('');watch(()=>[selected.value?.id,prep.value?.note],()=>note.value=prep.value?.note||'',{immediate:true});
const selectedSpace=computed(()=>state.spaces.find(s=>s.id===route.id));
const spaces=computed(()=>state.spaces.filter(s=>!route.q||`${s.id} ${s.studentName} ${s.name}`.includes(route.q)));
const defs=computed(()=>catalog().filter(o=>o.kind===(route.page==='targets'?'target':'material')&&(!route.q||`${o.name} ${o.id}`.includes(route.q))));
const chapters=computed(()=>catalog().filter(o=>o.kind==='chapter'&&o.relations.some(r=>r.label==='所属材料'&&r.ref.split('@')[0]===selected.value?.id)));
const mappings=computed(()=>catalog().filter(o=>o.kind==='mapping'&&o.relations.some(r=>r.label==='教材章节'&&r.ref.split('@')[0]===selected.value?.id)));
const targets=computed(()=>catalog().filter(o=>o.kind==='target'&&o.relations.some(r=>r.label==='适用章节'&&r.ref.split('@')[0]===selected.value?.id)));
function confirmSource(){if(!note.value.trim())throw Error('请记录核对结果及剩余疑点。');transact(s=>{const ch=selected.value?.id;if(!ch)throw Error('未选择章节');let p=s.preparations.find(p=>p.chapter===ch);if(!p){p={chapter:ch,reviewed:false,note:''};s.preparations.push(p);}p.reviewed=true;p.note=note.value.trim();p.at=new Date().toISOString();});}
</script>
<template><div class="wb-page">
<header class="page-header"><div><button v-if="route.returnTo.startsWith('#/textbooks?')" class="text-link" @click="back('textbooks')">← 返回教材章节</button><h2>{{title}}</h2><p class="page-desc">{{route.page==='learning-spaces'?'历史空间示例 · 保留原采用版本与学习记录；新版课程示例请从空间列表进入。':'在当前页面编辑并保存，自动保留对象版本和修改记录。'}}</p></div><button v-if="route.page==='textbooks'&&!route.id" class="btn primary" @click="newObject('material')">新增教材</button><button v-if="route.page==='targets'&&!route.id" class="btn primary" @click="newObject('target')">新增目标</button></header>
<template v-if="route.page==='learning-spaces'">
 <template v-if="selectedSpace"><button class="text-link" @click="go('learning-spaces')">← 返回空间列表</button><section class="panel"><h3>{{selectedSpace.name}}</h3><p>{{selectedSpace.studentName}} · {{selectedSpace.id}}</p><dl class="field-list"><dt>采用教材</dt><dd><ModelLink :to="selectedSpace.material" :scope="selectedSpace.id"/></dd><dt>学生选择的章节</dt><dd><ModelLink v-for="ch in selectedSpace.chapters" :key="ch" :to="ch" :scope="selectedSpace.id"/></dd><dt>采用目标</dt><dd><ModelLink :to="selectedSpace.target" :scope="selectedSpace.id"/></dd></dl><p class="callout">保存定义不会自动更新此空间。新版采用的简化操作仍待确定，当前保留原采用清单、所选章节及历史记录。</p><button class="btn" @click="go('students',{id:selectedSpace.studentId,scope:selectedSpace.id})">查看本空间学习状态</button></section>
 <section class="table-card"><h3>准确采用清单</h3><table class="data-table"><thead><tr><th>对象</th><th>采用版本</th><th>目录最新版本</th><th>类型</th></tr></thead><tbody><tr v-for="(version,id) in selectedSpace.adopted" :key="id"><td><ModelLink :to="`${id}@${version}`" :scope="selectedSpace.id"/></td><td>v{{version}}</td><td>v{{resolve(id)?.version}} <span v-if="resolve(id)?.version!==version" class="badge amber">存在新版，未自动采用</span></td><td>{{resolve(id)?kinds[resolve(id)!.kind]:'引用缺失'}}</td></tr></tbody></table></section>
 <section class="panel"><h3>采用历史</h3><div v-for="h in selectedSpace.history" :key="h.at" class="list-row"><div><p>{{h.at}} · {{h.reason}}</p><details><summary>查看原采用记录</summary><pre>{{JSON.stringify(h,null,2)}}</pre></details></div></div><p v-if="!selectedSpace.history.length" class="muted">尚未进行版本更新；当前使用初始示例版本。</p></section></template>
 <template v-else><div class="toolbar"><label>查找空间<input :value="route.q" @input="setQuery({q:($event.target as HTMLInputElement).value,p:1})"/></label></div><section class="table-card"><table class="data-table"><thead><tr><th>学生</th><th>空间</th><th>目标</th></tr></thead><tbody><tr v-for="s in spaces.slice((route.p-1)*10,route.p*10)" :key="s.id"><td>{{s.studentName}}</td><td><button class="text-link" @click="go('learning-spaces',{id:s.id})">{{s.name}}</button><small>{{s.id}}</small></td><td><ModelLink :to="s.target" :scope="s.id"/></td></tr></tbody></table></section><PagingBar :total="spaces.length"/></template>
</template>
<template v-else-if="!route.id"><div class="toolbar"><label>搜索{{route.page==='targets'?'目标':'教材'}}<input :value="route.q" @input="setQuery({q:($event.target as HTMLInputElement).value,p:1})" placeholder="名称或编号"/></label></div><section class="table-card"><table class="data-table"><thead><tr><th>名称</th><th>说明</th><th>版本</th><th>操作</th></tr></thead><tbody><tr v-for="o in defs.slice((route.p-1)*10,route.p*10)" :key="o.id"><td><button class="text-link" @click="go(route.page,{id:o.id})">{{o.name}}</button><small>{{o.id}}</small></td><td>{{o.summary}}</td><td>v{{o.version}}</td><td><button class="btn" @click="editObject(o.id)">编辑</button></td></tr></tbody></table><p v-if="!defs.length" class="empty">暂无符合条件的对象。</p></section><PagingBar :total="defs.length"/><ObjectDrafts :kind="route.page==='targets'?'target':'material'"/><p v-if="route.page==='textbooks'" class="muted">当前可维护教材条目、章节文本及映射。真实扫描导入和 OCR 尚未接入。</p></template>
<template v-else-if="selected"><button class="text-link" @click="go(route.page)">← 返回目录</button><section class="panel"><div class="row-between"><h3>{{selected.name}}</h3><div class="button-row"><button class="btn" @click="openObject(objectKey(selected))">版本与详情</button><button class="btn primary" @click="editObject(selected!.id)">编辑{{kinds[selected.kind]}}</button></div></div><p>{{selected.summary}}</p></section>
 <template v-if="selected.kind==='material'"><div class="row-between"><h3>章节</h3><button class="btn primary" @click="newObject('chapter','',selected!.id)">新增章节</button></div><section class="table-card"><table class="data-table"><thead><tr><th>章节</th><th>说明</th><th>操作</th></tr></thead><tbody><tr v-for="ch in chapters" :key="ch.id"><td><button class="text-link" @click="go('textbooks',{id:ch.id})">{{ch.name}}</button></td><td>{{ch.summary}}</td><td><button class="btn" @click="editObject(ch.id)">编辑</button></td></tr></tbody></table><p v-if="!chapters.length" class="empty">尚无章节，可在此新增。</p></section><ObjectDrafts kind="chapter" :parent="selected.id"/></template>
 <template v-else-if="selected.kind==='chapter'"><div class="tabs"><button v-for="(label,key) in {source:'来源与内容',mapping:'模型映射',target:'目标要求',readiness:'可用条件'}" :key="key" :class="{active:(route.tab||'source')===key}" @click="setQuery({tab:key})">{{label}}</button></div>
 <template v-if="!route.tab||route.tab==='source'"><div class="two-columns"><section class="panel"><h3>原始材料</h3><p class="source-text">{{selected.fields.原始材料}}</p></section><section class="panel"><h3>整理内容与参考</h3><p class="source-text">{{selected.fields.核对文本}}</p><p class="muted">{{selected.fields.待核对}}</p></section></div><section class="panel"><label>核对结果与剩余疑点<textarea v-model="note"/></label><button class="btn" @click="act(confirmSource)">保存核对结果</button><span class="badge" :class="prep?.reviewed?'green':'amber'">{{prep?.reviewed?'已核对':'待核对'}}</span></section></template>
 <section v-if="route.tab==='mapping'" class="panel"><div class="row-between"><h3>教材映射</h3><button class="btn primary" @click="newObject('mapping','',selected!.id)">新增映射</button></div><div v-for="m in mappings" :key="m.id"><ModelObjectContent :reference="m.id" tab="relations"/><button class="btn" @click="editObject(m.id)">编辑映射</button></div><p v-if="!mappings.length" class="empty">尚无本章映射。</p><ObjectDrafts kind="mapping" :parent="selected.id"/></section>
 <section v-if="route.tab==='target'" class="panel"><div class="row-between"><h3>本章目标</h3><button class="btn primary" @click="newObject('target','',selected!.id)">新增目标</button></div><div v-for="t in targets" :key="t.id" class="list-row"><div><ModelLink :to="objectKey(t)"/><p>{{t.requiredAspects?.map(k=>aspectNames[k]||k).join('、')}}</p></div><button class="btn" @click="editObject(t.id)">编辑目标</button></div><p v-if="!targets.length" class="empty">尚无本章目标。</p><ObjectDrafts kind="target" :parent="selected.id"/></section>
 <section v-if="route.tab==='readiness'" class="table-card"><table class="data-table"><thead><tr><th>行为</th><th>准备情况</th><th>依据与缺口</th></tr></thead><tbody><tr v-for="r in readiness(selected.id)" :key="r.label"><td>{{r.label}}</td><td>{{r.ready?'示例条件齐备':'待补'}}</td><td>{{r.reason}}</td></tr></tbody></table><p class="callout">这里检查内容是否齐备，不是审批步骤。保存定义不等于正式教学与评价引擎已经接通。</p></section>
 </template>
 <section v-else class="panel"><ModelObjectContent :reference="selected.id"/></section>
</template><p v-else class="empty">指定对象不存在。请返回目录选择。</p>
</div></template>
